package connectioncheck

// shortdetail_differential_test.go — the _short_detail differential:
// the reference's own outputs (run against the unmodified Python at
// the pinned rev 98f4fc7 through the session venv) byte-compared with
// the Go port — the pathy-paren scanner (a hand-rolled equivalent of
// Python's r"\s*\(([^()]*)\)" sub with the Unicode \s class), the
// all-pathy guard, the collapse, and the mid-ellipsis budget including
// the floor-dominated over-budget corner at small budgets.

import (
	"testing"
)

// cases generated by running the unmodified reference's
// connection_check._short_detail at rev 98f4fc7 (the venv run of
// SESSION-014; static facts, byte-compared below).
var shortDetailDifferential = []struct {
	detail string
	budget int
	want   string
}{
	{"found · writable — ready to receive notes · Obsidian vault (G:\\Docs\\GitHub Projects\\Obsidian Vault)", 72, "found · writable — ready to receive notes · Obsidian vault"},
	{"found · writable — ready to receive notes · Obsidian vault (G:/Docs/Documents/Obsidian Website Directory/)", 72, "found · writable — ready to receive notes · Obsidian vault"},
	{"valid — account assadigit (5000 req/h)", 72, "valid — account assadigit (5000 req/h)"},
	{"(G:\\only\\a\\path)", 72, "(G:\\only\\a\\path)"},
	{"a (b (c)) d", 72, "a (b (c)) d"},
	{"a (b (G:\\x)) d", 72, "a (b) d"},
	{" ( (x)", 72, "( (x)"},
	{"((x))", 72, "((x))"},
	{"(https://x.test) then (classic, 'repo' scope)", 72, "then (classic, 'repo' scope)"},
	{"\\\\server\\share (network)", 72, "\\\\server\\share (network)"},
	{"(5000 req/h) (G:\\x) (C:/y) plain", 72, "(5000 req/h) plain"},
	{"xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", 72, "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx…xxxxxxxxxxxxxxxxxxxxxxx"},
	{"ééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééééé", 72, "éééééééééééééééééééééééééééééééééééééééééééééééé…ééééééééééééééééééééééé"},
	{"no parens at all here", 72, "no parens at all here"},
	{"()", 72, "()"},
	{"(", 72, "("},
	{")", 72, ")"},
	{"a (b", 72, "a (b"},
	{"(unix:/abs/path) tail", 72, "tail"},
	{"(drive:X ok) tail", 72, "(drive:X ok) tail"},
	{"  leading and trailing  ", 72, "leading and trailing"},
	{"short", 36, "short"},
	{"a much longer detail that exceeds a small budget easily", 10, "a much longe…t easily"},
}

func TestShortDetailDifferential(t *testing.T) {
	for i, c := range shortDetailDifferential {
		got := shortDetail(c.detail, c.budget)
		if got != c.want {
			head := c.detail
			if len(head) > 40 {
				head = head[:40]
			}
			t.Errorf("case %d detail=%q… budget=%d:\n  got  %q\n  want %q",
				i, head, c.budget, got, c.want)
		}
	}
}
